/* Astro Blocks — tokens — MIT — https://github.com/lambda-curry/astro-blocks
   The semantic token contract every block reads. Each block also carries these
   values as var() fallbacks, so this file is optional: import it in your layout,
   or define the same names in your own theme. Override roles, not components. */
:root {
  /* Color roles */
  --color-bg: #ffffff;
  --color-surface: #f3f4f1;
  --color-text: #1b1f22;
  --color-muted: #555c62;
  --color-accent: #1f4f5f;
  --color-on-accent: #ffffff;
  --color-border: #8e979e;
  --color-link: var(--color-accent);
  --color-focus: var(--color-accent);

  /* Type */
  --font-body: system-ui, sans-serif;
  --font-display: system-ui, sans-serif;
  --step--1: clamp(0.875rem, 0.84rem + 0.16vw, 0.95rem);
  --step-0: clamp(1rem, 0.96rem + 0.2vw, 1.125rem);
  --step-1: clamp(1.2rem, 1.1rem + 0.5vw, 1.5rem);
  --step-2: clamp(1.45rem, 1.2rem + 1vw, 2rem);
  --step-3: clamp(1.75rem, 1.35rem + 1.8vw, 2.75rem);
  --step-4: clamp(2.15rem, 1.5rem + 2.8vw, 3.6rem);
  --step-5: clamp(2.6rem, 1.7rem + 4vw, 5rem);
  --leading-body: 1.6;
  --leading-display: 1.08;
  --weight-display: 650;
  --weight-action: 600;
  --tracking-display: -0.022em;

  /* Space and measure */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;
  --space-8: 4rem;
  --space-gutter: clamp(1.25rem, 4vw, 4rem);
  --section-gap: clamp(3rem, 8vw, 7rem);
  --width-content: 72rem;
  --width-wide: 90rem;
  --width-text: 68ch;

  /* Shape and motion */
  --radius-sm: 0.375rem;
  --radius-lg: 1rem;
  --duration: 160ms;
  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --duration: 0ms;
  }
}
